# HARBOR_CANARY: tests generated by Step3 pipeline v2
import json
import re
import csv
import io
import zipfile
from pathlib import Path
from xml.etree import ElementTree as ET

import pytest


TASK_ROOT = Path("/task_file")
INPUT_DIR = TASK_ROOT / "input"
CODE_DIR = TASK_ROOT / "code"

REQUIRED_INPUT_FILES = [
    "flight_search_results.json",
    "llm_routing_response.json",
    "cross_chain_swap_dry_run.json",
    "optimization_output.json",
    "health_check_response.json",
    "fixture_manifest.json",
    "manifest.yaml",
]

FUNCTIONAL_CODE_FILES = [
    "code/app.py",
    "code/config.py",
    "code/blueprints/health.py",
    "code/blueprints/roadmap.py",
    "code/utils/validators.py",
]

ALLOWED_ARTIFACT_TYPES = {
    "flight_search",
    "llm_routing",
    "cross_chain_swap",
    "optimization_output",
    "health_check",
    "fixture_manifest",
    "manifest_yaml",
}


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def _load_json(path: Path):
    """Load a JSON file and return parsed data."""
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def _read_text(path: Path) -> str:
    """Read a text file."""
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read()


def _file_exists_nonempty(path: Path) -> bool:
    """Check if a path exists, is a file, and has size > 0."""
    return path.is_file() and path.stat().st_size > 0


# ---------------------------------------------------------------------------
# 1. Integration manifest tests
# ---------------------------------------------------------------------------
class TestIntegrationManifest:
    """Tests for /task_file/integration_manifest.json."""

    MANIFEST_PATH = TASK_ROOT / "integration_manifest.json"

    def test_manifest_exists_and_parseable(self):
        """Manifest file must exist, be non-empty, and parse as valid JSON."""
        assert _file_exists_nonempty(self.MANIFEST_PATH), (
            f"{self.MANIFEST_PATH} must exist and be non-empty"
        )
        data = _load_json(self.MANIFEST_PATH)
        assert isinstance(data, dict), "Manifest must be a JSON object"

    def test_artifacts_array_present_and_count(self):
        """Manifest must contain an 'artifacts' array with exactly 7 entries."""
        data = _load_json(self.MANIFEST_PATH)
        assert "artifacts" in data, "Manifest must have top-level 'artifacts' key"
        artifacts = data["artifacts"]
        assert isinstance(artifacts, list), "'artifacts' must be an array"
        assert len(artifacts) == 7, (
            f"Expected 7 artifacts, got {len(artifacts)}"
        )

    def test_artifact_schema_and_paths(self):
        """Every artifact entry must have required keys with correct types and values."""
        data = _load_json(self.MANIFEST_PATH)
        artifacts = data["artifacts"]
        allowed_paths = {str(INPUT_DIR / f) for f in REQUIRED_INPUT_FILES}

        for entry in artifacts:
            assert isinstance(entry, dict), f"Artifact entry must be an object: {entry}"
            # Required keys
            for key in ("path", "status", "type", "digest"):
                assert key in entry, f"Artifact entry missing key '{key}': {entry}"

            # path
            path = entry["path"]
            assert isinstance(path, str), f"'path' must be a string: {path}"
            assert path.startswith("/task_file/input/"), (
                f"Path must start with /task_file/input/: {path}"
            )
            assert path in allowed_paths, f"Unexpected artifact path: {path}"

            # status
            assert entry["status"] == "present", (
                f"Status must be 'present' for {path}, got {entry['status']}"
            )

            # type
            assert entry["type"] in ALLOWED_ARTIFACT_TYPES, (
                f"Unknown type '{entry['type']}' for {path}"
            )

            # digest
            digest = entry["digest"]
            assert isinstance(digest, str) and len(digest) > 0, (
                f"Digest must be a non-empty string for {path}"
            )

    def test_artifacts_sorted_by_path(self):
        """Artifacts must be sorted alphabetically by path."""
        data = _load_json(self.MANIFEST_PATH)
        paths = [a["path"] for a in data["artifacts"]]
        assert paths == sorted(paths), (
            f"Artifacts not sorted by path. Got: {paths}"
        )

    def test_flight_search_digest_content(self):
        """Digest for flight_search_results.json must contain origin, destination, date, and offer count."""
        data = _load_json(self.MANIFEST_PATH)
        entry = self._find_entry(data, "flight_search")
        digest = entry["digest"]

        fixture = _load_json(INPUT_DIR / "flight_search_results.json")
        rp = fixture.get("request_params", {})
        origin = rp.get("origin", "?")
        destination = rp.get("destination", "?")
        date = rp.get("departure_date", "?")
        count = len(fixture.get("results", []))

        assert f"origin={origin}" in digest, f"Digest missing origin: {digest}"
        assert f"destination={destination}" in digest, f"Digest missing destination: {digest}"
        assert f"date={date}" in digest, f"Digest missing date: {digest}"
        assert f"offers={count}" in digest, f"Digest missing offers count: {digest}"

    def test_llm_routing_digest_content(self):
        """Digest for llm_routing_response.json must be first 120 chars of generated content."""
        data = _load_json(self.MANIFEST_PATH)
        entry = self._find_entry(data, "llm_routing")
        digest = entry["digest"]

        fixture = _load_json(INPUT_DIR / "llm_routing_response.json")
        choices = fixture.get("choices", [])
        assert choices, "llm_routing_response has no choices"
        content = choices[0].get("message", {}).get("content", "")
        expected = content[:120]

        assert digest == expected, (
            f"LLM routing digest mismatch.\nExpected: {expected}\nGot:      {digest}"
        )

    def test_cross_chain_swap_digest_content(self):
        """Digest for cross_chain_swap_dry_run.json must contain source_chain, target_chain, estimated_output."""
        data = _load_json(self.MANIFEST_PATH)
        entry = self._find_entry(data, "cross_chain_swap")
        digest = entry["digest"]

        fixture = _load_json(INPUT_DIR / "cross_chain_swap_dry_run.json")
        src = fixture.get("requestPreview", {}).get("source_chain", "?")
        tgt = fixture.get("requestPreview", {}).get("destination_chain", "?")
        est = fixture.get("estimated_cost", {}).get("total_estimated_usd", "?")

        assert f"source_chain={src}" in digest, f"Digest missing source_chain: {digest}"
        assert f"target_chain={tgt}" in digest, f"Digest missing target_chain: {digest}"
        assert f"estimated_output={est}" in digest, f"Digest missing estimated_output: {digest}"

    def test_optimization_output_digest_content(self):
        """Digest for optimization_output.json must contain model_id, prompt_count, total_billed."""
        data = _load_json(self.MANIFEST_PATH)
        entry = self._find_entry(data, "optimization_output")
        digest = entry["digest"]

        fixture = _load_json(INPUT_DIR / "optimization_output.json")
        model_id = fixture.get("source", "?")
        prompt_count = len(fixture.get("results", []))
        total_billed = fixture.get("billing_metadata", {}).get("estimated_cost_usd", "?")

        assert f"model_id={model_id}" in digest, f"Digest missing model_id: {digest}"
        assert f"prompt_count={prompt_count}" in digest, f"Digest missing prompt_count: {digest}"
        assert f"total_billed={total_billed}" in digest, f"Digest missing total_billed: {digest}"

    def test_health_check_digest_content(self):
        """Digest for health_check_response.json must contain status_code and status field."""
        data = _load_json(self.MANIFEST_PATH)
        entry = self._find_entry(data, "health_check")
        digest = entry["digest"]

        fixture = _load_json(INPUT_DIR / "health_check_response.json")
        status_code = fixture.get("status_code", "?")
        status_field = fixture.get("summary", {}).get("overall_status", "?")

        assert f"status_code={status_code}" in digest, f"Digest missing status_code: {digest}"
        assert f"status={status_field}" in digest, f"Digest missing status: {digest}"

    def test_fixture_manifest_digest_content(self):
        """Digest for fixture_manifest.json must contain top-level keys and entry count."""
        data = _load_json(self.MANIFEST_PATH)
        entry = self._find_entry(data, "fixture_manifest")
        digest = entry["digest"]

        fixture = _load_json(INPUT_DIR / "fixture_manifest.json")
        keys = sorted(fixture.keys())
        count = len(fixture.get("fixtures", []))

        assert f"keys={keys}" in digest, f"Digest missing keys: {digest}"
        assert f"entries={count}" in digest, f"Digest missing entries count: {digest}"

    def test_manifest_yaml_digest_content(self):
        """Digest for manifest.yaml must contain top-level keys and fixture entry count."""
        data = _load_json(self.MANIFEST_PATH)
        entry = self._find_entry(data, "manifest_yaml")
        digest = entry["digest"]

        raw = _read_text(INPUT_DIR / "manifest.yaml")
        keys = []
        fixtures_count = 0
        in_fixtures = False
        for line in raw.splitlines():
            stripped = line.lstrip()
            if stripped.startswith("#"):
                continue
            if stripped.startswith("fixture_manifest:"):
                continue
            if line.startswith("  ") and not line.startswith("    "):
                key = stripped.split(":")[0].strip()
                if key and not key.startswith("-"):
                    keys.append(key)
            if stripped.startswith("fixtures:"):
                in_fixtures = True
                continue
            if in_fixtures and stripped.startswith("- path:"):
                fixtures_count += 1

        expected_keys = sorted(set(keys))
        assert f"keys={expected_keys}" in digest, f"Digest missing keys: {digest}"
        assert f"entries={fixtures_count}" in digest, f"Digest missing entries count: {digest}"

    @staticmethod
    def _find_entry(manifest, artifact_type):
        for entry in manifest["artifacts"]:
            if entry["type"] == artifact_type:
                return entry
        pytest.fail(f"No artifact entry with type '{artifact_type}'")


# ---------------------------------------------------------------------------
# 2. OpenAPI specification tests
# ---------------------------------------------------------------------------
class TestOpenAPISpec:
    """Tests for /task_file/openapi_spec.json."""

    SPEC_PATH = TASK_ROOT / "openapi_spec.json"

    def test_spec_exists_and_parseable(self):
        """OpenAPI spec must exist, be non-empty, and parse as valid JSON."""
        assert _file_exists_nonempty(self.SPEC_PATH), (
            f"{self.SPEC_PATH} must exist and be non-empty"
        )
        data = _load_json(self.SPEC_PATH)
        assert isinstance(data, dict), "OpenAPI spec must be a JSON object"

    def test_openapi_version(self):
        """Top-level openapi field must be '3.0.3'."""
        data = _load_json(self.SPEC_PATH)
        assert data.get("openapi") == "3.0.3", (
            f"Expected openapi='3.0.3', got {data.get('openapi')}"
        )

    def test_info_section(self):
        """Info section must contain title and version."""
        data = _load_json(self.SPEC_PATH)
        info = data.get("info", {})
        assert isinstance(info, dict), "'info' must be an object"
        assert "title" in info and isinstance(info["title"], str), (
            "info.title must be a non-empty string"
        )
        assert "version" in info and isinstance(info["version"], str), (
            "info.version must be a non-empty string"
        )

    def test_health_endpoint_exists(self):
        """Paths must include the health GET endpoint."""
        data = _load_json(self.SPEC_PATH)
        paths = data.get("paths", {})
        health_path = paths.get("/api/v1/health")
        assert health_path is not None, "Missing /api/v1/health path"
        assert "get" in health_path, "Missing GET method for /api/v1/health"

    def test_health_endpoint_response_schema(self):
        """Health endpoint 200 response must include a 'status' property of type string."""
        data = _load_json(self.SPEC_PATH)
        health_get = data["paths"]["/api/v1/health"]["get"]
        responses = health_get.get("responses", {})
        resp_200 = responses.get("200", {})
        content = resp_200.get("content", {}).get("application/json", {})
        schema = content.get("schema", {})
        properties = schema.get("properties", {})
        assert "status" in properties, (
            "Health 200 response schema missing 'status' property"
        )
        assert properties["status"].get("type") == "string", (
            "Health 'status' property must be type string"
        )

    def test_roadmap_endpoint_exists(self):
        """Paths must include the roadmap generation POST endpoint."""
        data = _load_json(self.SPEC_PATH)
        paths = data.get("paths", {})
        roadmap_path = paths.get("/api/v1/roadmap/generate")
        assert roadmap_path is not None, "Missing /api/v1/roadmap/generate path"
        assert "post" in roadmap_path, "Missing POST method for /api/v1/roadmap/generate"

    def test_roadmap_endpoint_request_body(self):
        """Roadmap POST must have a requestBody with application/json schema requiring 'feature'."""
        data = _load_json(self.SPEC_PATH)
        post_op = data["paths"]["/api/v1/roadmap/generate"]["post"]
        assert "requestBody" in post_op, "Roadmap POST missing requestBody"
        req_body = post_op["requestBody"]
        json_content = req_body.get("content", {}).get("application/json", {})
        schema = json_content.get("schema", {})
        assert isinstance(schema, dict), "requestBody schema must be an object"
        required = schema.get("required", [])
        assert "feature" in required, (
            f"Roadmap requestBody schema must require 'feature', got required={required}"
        )


# ---------------------------------------------------------------------------
# 3. Code review report tests
# ---------------------------------------------------------------------------
class TestCodeReviewReport:
    """Tests for /task_file/code_review_report.md."""

    REPORT_PATH = TASK_ROOT / "code_review_report.md"

    def test_report_exists_and_nonempty(self):
        """Code review report must exist and be non-empty."""
        assert _file_exists_nonempty(self.REPORT_PATH), (
            f"{self.REPORT_PATH} must exist and be non-empty"
        )

    def test_functional_file_sections_present(self):
        """Every functional Python file must have a dedicated section heading."""
        report = _read_text(self.REPORT_PATH)
        for rel_path in FUNCTIONAL_CODE_FILES:
            heading = f"## {rel_path}"
            assert heading in report, (
                f"Report missing section heading for {rel_path}"
            )

    def test_sections_in_alphabetical_order(self):
        """File sections must appear in alphabetical order by relative path."""
        report = _read_text(self.REPORT_PATH)
        # Extract level-2 headings
        headings = re.findall(r"^## (.+)$", report, re.MULTILINE)
        # Filter to only functional file headings
        file_headings = [h for h in headings if h in FUNCTIONAL_CODE_FILES]
        assert file_headings == sorted(file_headings), (
            f"File sections not in alphabetical order: {file_headings}"
        )

    def test_each_section_has_severity_issue(self):
        """Each file section must contain at least one issue bullet starting with HIGH/MEDIUM/LOW:."""
        report = _read_text(self.REPORT_PATH)
        for rel_path in FUNCTIONAL_CODE_FILES:
            # Extract section body between this heading and the next heading or end
            pattern = re.compile(
                rf"^## {re.escape(rel_path)}$\n(.*?)(?=\n## |\Z)",
                re.DOTALL | re.MULTILINE
            )
            match = pattern.search(report)
            assert match, f"Could not extract section body for {rel_path}"
            body = match.group(1)
            assert re.search(r"^- (HIGH|MEDIUM|LOW):", body, re.MULTILINE), (
                f"Section {rel_path} missing severity-labelled issue bullet"
            )

    def test_no_placeholder_text(self):
        """Report must not contain obvious placeholder text."""
        report = _read_text(self.REPORT_PATH)
        placeholders = ["TODO", "TBD", "FIXME", "placeholder", "lorem ipsum"]
        for ph in placeholders:
            assert ph not in report, f"Report contains placeholder text: {ph}"


