class TestInputFilesPreserved:
    """Ensure required input files still exist and are non-empty."""

    @pytest.mark.parametrize("filename", REQUIRED_INPUT_FILES)
    def test_input_file_exists(self, filename):
        """Each required input file must still exist and be non-empty."""
        path = INPUT_DIR / filename
        assert _file_exists_nonempty(path), (
            f"Input file {path} must still exist and be non-empty"
        )
